SELECT game_id AS "gameId", provider_id AS "providerId", duration_formula_key AS "durationFormulaKey", max_stacks AS "maxStacks", refresh_policy_type_id AS "refreshPolicyTypeId", tick_interval_ms AS "tickIntervalMs", start_delay_ms AS "startDelayMs", tick_anchor_scope_type_id AS "tickAnchorScopeTypeId", tick_anchor_state_key AS "tickAnchorStateKey", change_revision AS "changeRevision", updated_at AS "updatedAt" FROM public.provider_lifecycles WHERE game_id = #{gameId}
AND provider_id = #{providerId}
ORDER BY provider_id
